import { compressToUTF16 } from './lzStringUtf16.ts';

interface CompressRequest {
    id: number;
    json: string;
}

interface CompressResponse {
    id: number;
    compressed?: string;
    error?: string;
}

const scope = globalThis as unknown as {
    onmessage: ((event: MessageEvent<CompressRequest>) => void) | null;
    postMessage: (message: CompressResponse) => void;
};

scope.onmessage = (event) => {
    const request = event.data;
    if (!request || typeof request.id !== 'number' || typeof request.json !== 'string') return;
    try {
        scope.postMessage({ id: request.id, compressed: compressToUTF16(request.json) });
    } catch (error) {
        scope.postMessage({
            id: request.id,
            error: error instanceof Error ? error.message : String(error),
        });
    }
};
